# Search simple_note for likely dinner-related notes by query variations
sup_pw = {p['account_name']: p['password'] for p in apis.supervisor.show_account_passwords()}
simple_note_token = apis.simple_note.login(username='cod.smith@gmail.com', password=sup_pw['simple_note'])['access_token']


def search_all(query):
    out=[]
    i=0
    while True:
        page=apis.simple_note.search_notes(access_token=simple_note_token, query=query, page_index=i, page_limit=20)
        print('query',repr(query),'page',i,'len',len(page))
        if not page:
            break
        out.extend(page)
        i+=1
    return out

candidates = {}
for q in ['dinner','work dinner','Work Dinner','coworker','co-worker','bill','restaurant','splitting','split']:
    notes=search_all(q)
    # take only ones whose title or tags look relevant
    filtered=[n for n in notes if ('dinner' in n.get('title','').lower() or 'dinner' in ' '.join(n.get('tags',[])).lower() or 'work' in n.get('title','').lower())]
    candidates[q]=filtered
    print('q',q,'total',len(notes),'filtered',len(filtered))
    # print up to 3 titles
    for n in filtered[:3]:
        print('  ',n['note_id'],n['title'],n.get('tags'))

# Print union of candidates by note_id
union={}
for q,vals in candidates.items():
    for n in vals:
        union[n['note_id']]=n
print('UNION size',len(union))
for nid,n in list(union.items())[:20]:
    print(nid,n['title'],n.get('tags'))

