# Verify created Venmo payment requests exist
sup_pw={p['account_name']:p['password'] for p in apis.supervisor.show_account_passwords()}
venmo_token=apis.venmo.login(username='cod.smith@gmail.com', password=sup_pw['venmo'])['access_token']

created_ids={6097,6098,6099}
found=[]
page_index=0
page_limit=20
while True:
    page=apis.venmo.show_sent_payment_requests(access_token=venmo_token, page_index=page_index, page_limit=page_limit)
    print('sent_payment_requests page',page_index,'len',len(page))
    if not page:
        break
    for pr in page:
        if pr.get('payment_request_id') in created_ids:
            found.append(pr)
    page_index+=1

print('found',len(found))
for pr in sorted(found, key=lambda x: x.get('payment_request_id')):
    print('id',pr.get('payment_request_id'),'amount',pr.get('amount'),'desc',repr(pr.get('description')),'to',pr.get('receiver',{}).get('email'))
